$ErrorActionPreference = 'Stop'

# Generated by RoleCraft - https://rolecraft.omhinge.cloud
# Creates an IAM role with its trust policy and permissions.

$RoleName = 'github-deploy'

# Trust policy: who can assume the role
[System.IO.File]::WriteAllText((Join-Path $PWD.ProviderPath 'trust.json'), @'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Federated": "arn:aws:iam::123456789012:oidc-provider/token.actions.githubusercontent.com"
      },
      "Action": "sts:AssumeRoleWithWebIdentity",
      "Condition": {
        "StringEquals": {
          "token.actions.githubusercontent.com:aud": "sts.amazonaws.com",
          "token.actions.githubusercontent.com:sub": "repo:omhinge/site:ref:refs/heads/main"
        }
      }
    }
  ]
}
'@)

# Permissions policy
[System.IO.File]::WriteAllText((Join-Path $PWD.ProviderPath 'policy.json'), @'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "S3ReadWriteList",
      "Effect": "Allow",
      "Action": "s3:ListBucket",
      "Resource": "arn:aws:s3:::site-assets"
    },
    {
      "Sid": "S3ReadWriteObjects",
      "Effect": "Allow",
      "Action": [
        "s3:AbortMultipartUpload",
        "s3:GetObject",
        "s3:GetObjectVersion",
        "s3:ListMultipartUploadParts",
        "s3:PutObject"
      ],
      "Resource": "arn:aws:s3:::site-assets/*"
    },
    {
      "Sid": "CloudfrontCustomScoped",
      "Effect": "Allow",
      "Action": "cloudfront:CreateInvalidation",
      "Resource": "arn:aws:cloudfront::123456789012:distribution/E2EXAMPLE"
    }
  ]
}
'@)

# GitHub Actions needs an OIDC identity provider in this account (created once).
$existing = aws iam list-open-id-connect-providers --query "OpenIDConnectProviderList[?ends_with(Arn, '/token.actions.githubusercontent.com')].Arn" --output text --no-cli-pager
if ($LASTEXITCODE -ne 0) { throw "aws failed: list-open-id-connect-providers" }
if (-not $existing -or $existing -eq 'None') {
  aws iam create-open-id-connect-provider --url https://token.actions.githubusercontent.com --client-id-list sts.amazonaws.com --no-cli-pager | Out-Null
  if ($LASTEXITCODE -ne 0) { throw "aws failed: create-open-id-connect-provider" }
}

aws iam create-role --role-name $RoleName --assume-role-policy-document file://trust.json --description 'Created with RoleCraft' --no-cli-pager | Out-Null
if ($LASTEXITCODE -ne 0) { throw "aws failed: create-role" }
$PolicyArn = aws iam create-policy --policy-name "${RoleName}-policy" --policy-document file://policy.json --query Policy.Arn --output text --no-cli-pager
if ($LASTEXITCODE -ne 0) { throw "aws failed: create-policy" }
aws iam attach-role-policy --role-name $RoleName --policy-arn $PolicyArn --no-cli-pager
if ($LASTEXITCODE -ne 0) { throw "aws failed: attach-role-policy" }

Write-Output "Created role $RoleName."
Write-Output "Created and attached policy ${RoleName}-policy."
